}

function deleteSelected() {
  if (!state.sel.size) return toast('先选中对象再删除');
  pushUndo();
  const n = state.sel.size;
  state.objects = state.objects.filter(o => !state.sel.has(o.id));
  state.sel.clear();
  fullRender();
  toast(`已删除 ${n} 个对象（可撤销）`);
}

function nudgeSelected(dx, dy) {
  let moved = false;
