/* Locus · 落位画布 —— dark spatial canvas */
* { box-sizing: border-box; margin: 0; padding: 0; }
:root {
  --bg: #0e1013;
  --panel: #16191f;
  --line: #262b34;
  --ink: #e7ebf2;
  --ink-dim: #8b93a3;
  --accent: #7aa2ff;
  --pool: #38bdf8;
  --staged: #fbbf24;
  --locked: #34d399;
}
html, body { height: 100%; }
body {
  background: var(--bg);
  color: var(--ink);
  font: 14px/1.5 "Segoe UI", system-ui, "Microsoft YaHei", sans-serif;
  display: flex; flex-direction: column;
  overflow: hidden;
}

/* ---------- top bar ---------- */
#topbar {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 8px 14px; background: var(--panel); border-bottom: 1px solid var(--line);
  flex: 0 0 auto; z-index: 20;
}
.brand { display: flex; align-items: baseline; gap: 8px; white-space: nowrap; }
.logo { color: var(--accent); font-size: 16px; }
.name { font-weight: 700; font-size: 15px; letter-spacing: .5px; }
.tagline { color: var(--ink-dim); font-size: 12px; }
.tools { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
button {
  background: #1d222b; color: var(--ink); border: 1px solid var(--line);
  border-radius: 6px; padding: 4px 10px; font: inherit; font-size: 12.5px; cursor: pointer;
}
button:hover { background: #262d3a; border-color: #38414f; }
button:active { transform: translateY(1px); }
button.toggle.on { background: #223258; border-color: var(--accent); color: #cdd9ff; }
.sep { width: 1px; height: 18px; background: var(--line); margin: 0 4px; }
kbd {
  font: 11px/1 Consolas, monospace; background: #0b0d10; border: 1px solid #333b47;
  border-bottom-width: 2px; border-radius: 4px; padding: 1px 5px; color: var(--ink-dim);
}

/* ---------- canvas ---------- */
#viewport {
  flex: 1 1 auto; position: relative; overflow: hidden;
  cursor: default; touch-action: none; user-select: none;
}
#viewport.panning { cursor: grabbing; }
#world {
  position: absolute; left: -600px; top: -400px;
  width: 3600px; height: 2600px; transform-origin: 0 0;
  background-image:
    linear-gradient(rgba(255,255,255,.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.045) 1px, transparent 1px);
  background-size: 20px 20px;
}

/* zones */
.zone {
  position: absolute; border-radius: 14px;
  border: 1.5px dashed color-mix(in srgb, var(--zc) 55%, transparent);
  background: color-mix(in srgb, var(--zc) 7%, transparent);
  transition: background .15s;
}
.zone.hot { background: color-mix(in srgb, var(--zc) 16%, transparent); border-style: solid; }
.zone-head {
  display: flex; align-items: baseline; gap: 8px;
  padding: 10px 14px 4px; color: var(--zc);
}
.zone-head .zname { font-weight: 700; font-size: 14px; letter-spacing: .5px; }
.zone-head .zcount {
  font: 11px Consolas, monospace; background: color-mix(in srgb, var(--zc) 22%, transparent);
  border-radius: 9px; padding: 0 7px;
}
.zone-head .zhint { color: var(--ink-dim); font-size: 11.5px; margin-left: auto; }

/* objects */
.obj {
  position: absolute; display: flex; gap: 8px; align-items: stretch;
  background: #1b2029; border: 1px solid #2c3442; border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,.45);
  cursor: grab; overflow: hidden;
}
.obj:hover { border-color: #3d4757; }
.obj.dragging { cursor: grabbing; opacity: .92; box-shadow: 0 8px 22px rgba(0,0,0,.6); }
.obj.selected { border-color: var(--accent); box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent) 45%, transparent), 0 4px 14px rgba(0,0,0,.5); }
.obj-bar { width: 5px; border-radius: 0; flex: 0 0 auto; }
.obj.zone-pool .obj-bar { background: var(--pool); }
.obj.zone-staged .obj-bar { background: var(--staged); }
.obj.zone-locked .obj-bar { background: var(--locked); }
.obj.zone-none .obj-bar { background: #5b6474; }
.obj-body { flex: 1 1 auto; padding: 7px 10px 6px 2px; min-width: 0; }
.obj-title {
  font-weight: 600; font-size: 13.5px; line-height: 1.35;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; outline: none;
}
.obj-title[contenteditable="true"] {
  white-space: normal; background: #0e1116; border: 1px solid var(--accent);
  border-radius: 4px; padding: 0 4px; margin: -1px -4px; cursor: text; user-select: text;
}
.obj-meta { display: flex; align-items: center; gap: 6px; margin-top: 3px; font-size: 11px; color: var(--ink-dim); }
.obj-meta .dot { width: 7px; height: 7px; border-radius: 50%; }
.obj.zone-pool .dot { background: var(--pool); }
.obj.zone-staged .dot { background: var(--staged); }
.obj.zone-locked .dot { background: var(--locked); }
.obj.zone-none .dot { background: #5b6474; }

/* rubber band */
#band {
  position: absolute; border: 1px dashed var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  pointer-events: none; z-index: 9999;
}

/* ---------- status bar ---------- */
#statusbar {
  flex: 0 0 auto; display: flex; align-items: center; gap: 8px;
  padding: 5px 14px; background: var(--panel); border-top: 1px solid var(--line);
  font-size: 12px; color: var(--ink-dim); white-space: nowrap;
}
#st-toast { color: var(--locked); margin-left: 10px; }
#st-hint { margin-left: auto; }
#st-hint b { color: var(--ink); }

/* ---------- help overlay ---------- */
#help {
  position: fixed; inset: 0; z-index: 100;
  background: rgba(6,8,11,.62); backdrop-filter: blur(2px);
  display: flex; align-items: center; justify-content: center;
}
.help-card {
  width: min(680px, 92vw); max-height: 86vh; overflow: auto;
  background: var(--panel); border: 1px solid #333b47; border-radius: 12px;
  padding: 18px 22px 14px; box-shadow: 0 18px 60px rgba(0,0,0,.6);
}
.help-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.help-head h2 { font-size: 15px; }
.help-card table { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.help-card th, .help-card td { text-align: left; padding: 6px 8px; border-bottom: 1px solid var(--line); }
.help-card th { color: var(--ink-dim); font-weight: 600; font-size: 11.5px; }
.help-foot { margin-top: 10px; color: var(--ink-dim); font-size: 12px; }

